//! Translation spec types and operations

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::collections::BTreeMap;
use std::path::Path;

/// Global translation spec (lives in tspec/*.toml)
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct GlobalSpec {
    pub target: Option<TargetConfig>,
    pub build: Option<BuildConfig>,
    pub linker: Option<LinkerConfig>,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct TargetConfig {
    pub triple: Option<String>,
    pub custom_target: Option<String>, // path to .json target file
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct BuildConfig {
    pub no_std: Option<bool>,
    pub panic: Option<String>,
    pub requires_nightly: Option<bool>,
    pub build_std: Option<Vec<String>>,
    pub rustflags: Option<Vec<String>>,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct LinkerConfig {
    pub args: Option<Vec<String>>,
    pub version_script: Option<String>,
}

/// Local crate config (lives in <crate>/tspec/config.toml)
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct LocalConfig {
    #[serde(default)]
    pub compat: Vec<String>,
    #[serde(default)]
    pub incompat: Vec<String>,
    #[serde(default)]
    pub mods: BTreeMap<String, SpecMods>,
}

/// Modifications to apply to a global spec
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct SpecMods {
    pub build: Option<BuildMods>,
    pub linker: Option<LinkerMods>,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct BuildMods {
    pub rustflags: Option<ArgMods>,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct LinkerMods {
    pub args: Option<ArgMods>,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct ArgMods {
    #[serde(default)]
    pub add: Vec<String>,
    #[serde(default)]
    pub remove: Vec<String>,
}

impl GlobalSpec {
    /// Load a global spec from a TOML file
    pub fn load(path: &Path) -> Result<Self> {
        let content = std::fs::read_to_string(path)
            .with_context(|| format!("failed to read spec: {}", path.display()))?;
        toml::from_str(&content)
            .with_context(|| format!("failed to parse spec: {}", path.display()))
    }

    /// Apply local modifications to produce a resolved spec
    pub fn apply_mods(&self, mods: Option<&SpecMods>) -> GlobalSpec {
        let Some(mods) = mods else {
            return self.clone();
        };

        let mut resolved = self.clone();

        // Apply build.rustflags mods
        if let Some(build_mods) = &mods.build {
            if let Some(rustflags_mods) = &build_mods.rustflags {
                let build = resolved.build.get_or_insert_with(Default::default);
                let flags = build.rustflags.get_or_insert_with(Vec::new);
                apply_arg_mods(flags, rustflags_mods);
            }
        }

        // Apply linker.args mods
        if let Some(linker_mods) = &mods.linker {
            if let Some(args_mods) = &linker_mods.args {
                let linker = resolved.linker.get_or_insert_with(Default::default);
                let args = linker.args.get_or_insert_with(Vec::new);
                apply_arg_mods(args, args_mods);
            }
        }

        resolved
    }

    /// Compute a hash of the resolved spec for target-dir naming
    pub fn hash(&self) -> String {
        // Serialize to canonical form (BTreeMap ensures consistent ordering)
        let canonical = toml::to_string(self).expect("spec should serialize");
        let mut hasher = Sha256::new();
        hasher.update(canonical.as_bytes());
        let result = hasher.finalize();
        hex::encode(&result[..4]) // 8 hex chars
    }
}

impl LocalConfig {
    /// Load local config from a crate's tspec/config.toml
    pub fn load(path: &Path) -> Result<Self> {
        let content = std::fs::read_to_string(path)
            .with_context(|| format!("failed to read config: {}", path.display()))?;
        toml::from_str(&content)
            .with_context(|| format!("failed to parse config: {}", path.display()))
    }

    /// Load or return default if file doesn't exist
    pub fn load_or_default(path: &Path) -> Result<Self> {
        if path.exists() {
            Self::load(path)
        } else {
            Ok(Self::default())
        }
    }

    /// Save config to file
    pub fn save(&self, path: &Path) -> Result<()> {
        let content = toml::to_string_pretty(self)
            .context("failed to serialize config")?;
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)
                .with_context(|| format!("failed to create dir: {}", parent.display()))?;
        }
        std::fs::write(path, content)
            .with_context(|| format!("failed to write config: {}", path.display()))
    }

    /// Check if a spec is compatible (not in incompat, and either no compat list or in compat list)
    pub fn is_compatible(&self, spec_name: &str) -> bool {
        if self.incompat.contains(&spec_name.to_string()) {
            return false;
        }
        if self.compat.is_empty() {
            return true; // No compat list = all compatible
        }
        self.compat.contains(&spec_name.to_string())
    }
}

fn apply_arg_mods(args: &mut Vec<String>, mods: &ArgMods) {
    // Remove first
    args.retain(|a| !mods.remove.contains(a));
    // Then add
    for arg in &mods.add {
        if !args.contains(arg) {
            args.push(arg.clone());
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_is_compatible_empty_config() {
        let config = LocalConfig::default();
        assert!(config.is_compatible("any-spec"));
    }

    #[test]
    fn test_is_compatible_incompat_blocks() {
        let config = LocalConfig {
            incompat: vec!["blocked".to_string()],
            ..Default::default()
        };
        assert!(!config.is_compatible("blocked"));
        assert!(config.is_compatible("other"));
    }

    #[test]
    fn test_is_compatible_compat_allowlist() {
        let config = LocalConfig {
            compat: vec!["allowed".to_string()],
            ..Default::default()
        };
        assert!(config.is_compatible("allowed"));
        assert!(!config.is_compatible("other"));
    }
}

//! Spec discovery and resolution

use anyhow::{bail, Context, Result};
use std::path::{Path, PathBuf};

use crate::tspec::{GlobalSpec, LocalConfig, SpecMods};

/// Workspace-level spec operations
pub struct SpecManager {
    workspace_root: PathBuf,
}

impl SpecManager {
    pub fn new(workspace_root: PathBuf) -> Self {
        Self { workspace_root }
    }

    /// Find workspace root by looking for Cargo.toml with [workspace]
    pub fn find_workspace() -> Result<Self> {
        let mut dir = std::env::current_dir()?;
        loop {
            let cargo_toml = dir.join("Cargo.toml");
            if cargo_toml.exists() {
                let content = std::fs::read_to_string(&cargo_toml)?;
                if content.contains("[workspace]") {
                    return Ok(Self::new(dir));
                }
            }
            if !dir.pop() {
                bail!("could not find workspace root");
            }
        }
    }

    /// Path to global tspec directory
    pub fn tspec_dir(&self) -> PathBuf {
        self.workspace_root.join("tspec")
    }

    /// List all available global specs
    pub fn list_global_specs(&self) -> Result<Vec<String>> {
        let tspec_dir = self.tspec_dir();
        if !tspec_dir.exists() {
            return Ok(vec![]);
        }

        let mut specs = vec![];
        for entry in std::fs::read_dir(&tspec_dir)? {
            let entry = entry?;
            let path = entry.path();
            if path.extension().is_some_and(|e| e == "toml") {
                if let Some(stem) = path.file_stem() {
                    specs.push(stem.to_string_lossy().to_string());
                }
            }
        }
        specs.sort();
        Ok(specs)
    }

    /// Load a global spec by name
    pub fn load_global_spec(&self, name: &str) -> Result<GlobalSpec> {
        let path = self.tspec_dir().join(format!("{name}.toml"));
        GlobalSpec::load(&path)
    }

    /// Path to a crate's tspec config
    pub fn crate_config_path(&self, crate_name: &str) -> Result<PathBuf> {
        let crate_path = self.find_crate_path(crate_name)?;
        Ok(crate_path.join("tspec").join("config.toml"))
    }

    /// Load a crate's local config
    pub fn load_local_config(&self, crate_name: &str) -> Result<LocalConfig> {
        let path = self.crate_config_path(crate_name)?;
        LocalConfig::load_or_default(&path)
    }

    /// Save a crate's local config
    pub fn save_local_config(&self, crate_name: &str, config: &LocalConfig) -> Result<()> {
        let path = self.crate_config_path(crate_name)?;
        config.save(&path)
    }

    /// Resolve a spec for a crate (global + local mods)
    pub fn resolve_spec(&self, spec_name: &str, crate_name: &str) -> Result<GlobalSpec> {
        let global = self.load_global_spec(spec_name)?;
        let local = self.load_local_config(crate_name)?;
        let mods = local.mods.get(spec_name);
        Ok(global.apply_mods(mods))
    }

    /// Get the target directory for a resolved spec
    pub fn target_dir(&self, spec_name: &str, resolved: &GlobalSpec) -> PathBuf {
        let hash = resolved.hash();
        self.workspace_root.join("target").join(format!("{spec_name}-{hash}"))
    }

    /// Find a crate's path within the workspace
    fn find_crate_path(&self, crate_name: &str) -> Result<PathBuf> {
        // Check common locations
        let candidates = [
            self.workspace_root.join(crate_name),
            self.workspace_root.join("apps").join(crate_name),
            self.workspace_root.join("tools").join(crate_name),
        ];

        for path in candidates {
            if path.join("Cargo.toml").exists() {
                return Ok(path);
            }
        }

        bail!("crate not found: {crate_name}");
    }

    /// List specs compatible with a crate
    pub fn list_compatible_specs(&self, crate_name: &str) -> Result<Vec<String>> {
        let local = self.load_local_config(crate_name)?;
        let all_specs = self.list_global_specs()?;

        Ok(all_specs
            .into_iter()
            .filter(|s| local.is_compatible(s))
            .collect())
    }
}

