use anyhow::Result;
use clap::{Parser, Subcommand};

mod spec;
mod tspec;

#[derive(Parser)]
#[command(name = "xt")]
#[command(about = "Translation spec based build system")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Build a crate with a translation spec
    Build {
        /// Crate to build
        crate_name: String,
        /// Translation spec to use
        #[arg(short = 't', long = "tspec")]
        tspec: String,
        /// Release build
        #[arg(short, long)]
        release: bool,
    },
    /// Build and run a crate with a translation spec
    Run {
        /// Crate to run
        crate_name: String,
        /// Translation spec to use
        #[arg(short = 't', long = "tspec")]
        tspec: String,
        /// Release build
        #[arg(short, long)]
        release: bool,
    },
    /// Manage crate compatibility with specs
    Compat {
        /// Crate name
        crate_name: String,
        /// Spec to add to compat list (omit to show current state)
        spec: Option<String>,
    },
    /// Mark a spec as incompatible with a crate
    Incompat {
        /// Crate name
        crate_name: String,
        /// Spec to add to incompat list
        spec: String,
    },
    /// Show or manage translation specs
    Spec {
        #[command(subcommand)]
        command: SpecCommands,
    },
}

#[derive(Subcommand)]
enum SpecCommands {
    /// List available global specs
    List,
    /// Show a spec (resolved with local mods if --crate specified)
    Show {
        /// Spec name
        name: String,
        /// Crate to apply local mods from
        #[arg(long = "crate")]
        crate_name: Option<String>,
    },
    /// Show the hash of a resolved spec
    Hash {
        /// Spec name
        name: String,
        /// Crate to apply local mods from
        #[arg(long = "crate")]
        crate_name: Option<String>,
    },
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Build { crate_name, tspec, release } => {
            println!("build: crate={crate_name} tspec={tspec} release={release}");
            // TODO: implement
        }
        Commands::Run { crate_name, tspec, release } => {
            println!("run: crate={crate_name} tspec={tspec} release={release}");
            // TODO: implement
        }
        Commands::Compat { crate_name, spec } => {
            match spec {
                Some(s) => println!("compat add: crate={crate_name} spec={s}"),
                None => println!("compat show: crate={crate_name}"),
            }
            // TODO: implement
        }
        Commands::Incompat { crate_name, spec } => {
            println!("incompat add: crate={crate_name} spec={spec}");
            // TODO: implement
        }
        Commands::Spec { command } => {
            match command {
                SpecCommands::List => {
                    println!("spec list");
                    // TODO: implement
                }
                SpecCommands::Show { name, crate_name } => {
                    println!("spec show: name={name} crate={crate_name:?}");
                    // TODO: implement
                }
                SpecCommands::Hash { name, crate_name } => {
                    println!("spec hash: name={name} crate={crate_name:?}");
                    // TODO: implement
                }
            }
        }
    }

    Ok(())
}

